function Get-Reduced {
  param("'$path)
  $raw = Get-Content -LiteralPath $path -Raw -Encoding UTF8
  $doc = $raw | ConvertFrom-Json
  $arr = @()
  if ($null -ne $doc.enforced_reduced_packages) {
    foreach ($item in $doc.enforced_reduced_packages) {
      if ($item -is [string]) { $arr += [pscustomobject]@{kind='"'str'; package="'$item; user=$null; policy=$null} }
      else { $arr += [pscustomobject]@{kind='"'dict'; package="'$item.package; user=$item.user; policy=$item.whitelist_policy} }
    }
  }
  $kab = $null
  if ($null -ne $doc.keep_alive_background) { $kab = $doc.keep_alive_background }
  $cand = @()
  if ($null -ne $doc.candidate_nmb_next) {
    foreach ($item in $doc.candidate_nmb_next) {
      if ($item.package) { $cand += $item.package } else { $cand += [string]$item }
    }
  }
  [pscustomobject]@{
    path=$path
    exists=(Test-Path -LiteralPath $path)
    size=(Get-Item -LiteralPath $path).Length
    mtime=(Get-Item -LiteralPath $path).LastWriteTime.ToString('"'yyyy-MM-dd HH:mm:ss')
    reduced="'$arr
    names=@($arr | ForEach-Object { $_.package })
    keep_alive_present=($null -ne $kab)
    keep_alive=$kab
    candidate=$cand
    top_keys=@($doc.PSObject.Properties.Name)
  }
}
$parsed = @{}
foreach ($k in $files.Keys) {
  $parsed[$k] = Get-Reduced $files[$k]
  $p = $parsed[$k]
  Write-Output "FILE $k"
  Write-Output ("PATH " + $p.path)
  Write-Output ("EXISTS " + $p.exists + " SIZE " + $p.size + " MTIME " + $p.mtime)
  Write-Output ("TOP_KEYS " + ($p.top_keys -join '"','))
  Write-Output (\"COUNT \" + "'$p.names.Count)
  $i=1
  foreach ($it in $p.reduced) {
    Write-Output ("  {0:D2} {1} user={2} policy={3}" -f $i, $it.package, $it.user, $it.policy)
    $i++
  }
  Write-Output ("KEEP_ALIVE_PRESENT " + $p.keep_alive_present)
  if ($p.keep_alive_present) {
    $kab = $p.keep_alive
    Write-Output ("KEEP_ALIVE_TYPE " + $kab.GetType().FullName)
    Write-Output ("KEEP_ALIVE_KEYS " + (@($kab.PSObject.Properties.Name) -join '"','))
    "'$kab | ConvertTo-Json -Depth 8
  }
  Write-Output ("CAND_NMB_COUNT " + $p.candidate.Count)
  $p.candidate | ForEach-Object { Write-Output ("  CAND " + $_) }
  Write-Output '"'---'
}
"'$cur = [System.Collections.Generic.HashSet[string]]::new([string[]]$parsed['"'current'].names)
foreach ("'$k in @('"'bak_before_keep_freq','bak_before_restore_floattasks','bak_before_stage5_keepalive')) {
  "'$bakNames = @($parsed[$k].names)
  $bak = [System.Collections.Generic.HashSet[string]]::new([string[]]$bakNames)
  $onlyCur = @($parsed['"'current'].names | Where-Object { -not "'$bak.Contains($_) })
  $onlyBak = @($bakNames | Where-Object { -not $cur.Contains($_) })
  Write-Output "DIFF $k"
  Write-Output ("  bak_count={0} cur_count={1}" -f $bakNames.Count, $parsed['"'current'].names.Count)
  Write-Output (\"  only_in_current_not_bak=\" + (("'$onlyCur | Sort-Object) -join '"','))
  Write-Output (\"  only_in_bak_not_current=\" + (("'$onlyBak | Sort-Object) -join '"','))
}"

