function Get-JsonSlice {
  param("'$path,$startPat,$endPat)
  $lines = Get-Content -LiteralPath $path -Encoding UTF8
  $start=-1; $end=-1
  for ($i=0; $i -lt $lines.Count; $i++) {
    if ($start -lt 0 -and $lines[$i] -match $startPat) { $start=$i }
    elseif ($start -ge 0 -and $end -lt 0 -and $lines[$i] -match $endPat -and $i -gt $start) { $end=$i; break }
  }
  Write-Output ('"'FILE ' + "'$path)
  Write-Output ('"'SLICE ' + ("'$start+1) + '"'-' + "'$(if($end -ge 0){$end+1}else{'"'EOF'}))
  if ("'$start -ge 0) {
    $to = if ($end -ge 0) { $end } else { [Math]::Min($start+80, $lines.Count-1) }
    for ($i=$start; $i -le $to; $i++) { Write-Output (('"'{0}: {1}' -f ("'$i+1), $lines[$i])) }
  }
}
